; ---- subPxY = subgridToPx( playTop, player[ pi ].y )
        mov     ax, 10
        push    ax                          ; save lhs: rhs is not a leaf
        mov     al, [drawPaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [player__y + bx]
        sar     ax, 1                       ; signed >>
        sar     ax, 1
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [subPxY], ax
; ---- subPxY2 = subPxY + paddleH - 1
        mov     ax, [subPxY]
        add     ax, 9
        dec     ax
        mov     [subPxY2], ax
; ---- drawLineVertical( paddleX[ pi ], subPxY, subPxY2, paddleColor[ pi ] )
        mov     al, [drawPaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [paddleX + bx]
        mov     [drawLineVertical__x], al   ; u8 -> u8, no widening
        mov     ax, [subPxY]
        mov     [drawLineVertical__y1], al  ; narrowed to u8
        mov     ax, [subPxY2]
        mov     [drawLineVertical__y2], al  ; narrowed to u8
        mov     al, [drawPaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [paddleColor + bx]
        mov     [drawLineVertical__color], al; u8 -> u8, no widening
        call    drawLineVertical
        ret

; ============================================== sub clearPaddle ====

clearPaddle:
; ---- subPxY = subgridToPx( playTop, player[ pi ].oldY )
        mov     ax, 10
        push    ax                          ; save lhs: rhs is not a leaf
        mov     al, [clearPaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [player__oldY + bx]
        sar     ax, 1                       ; signed >>
        sar     ax, 1
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [subPxY], ax
; ---- subPxY2 = subPxY + paddleH - 1
        mov     ax, [subPxY]
        add     ax, 9
        dec     ax
        mov     [subPxY2], ax
; ---- drawLineVertical( paddleX[ pi ], subPxY, subPxY2, lightGreen )
        mov     al, [clearPaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [paddleX + bx]
        mov     [drawLineVertical__x], al   ; u8 -> u8, no widening
        mov     ax, [subPxY]
        mov     [drawLineVertical__y1], al  ; narrowed to u8
        mov     ax, [subPxY2]
        mov     [drawLineVertical__y2], al  ; narrowed to u8
        mov     byte [drawLineVertical__color], 1
        call    drawLineVertical
        ret

; ============================================== sub drawBall ====

drawBall:
; ---- subPxX = subgridToPx( playLeft, ballX )
        mov     ax, 41
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [ballX]
        sar     ax, 1                       ; signed >>
        sar     ax, 1
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [subPxX], ax
; ---- subPxY = subgridToPx( playTop, ballY )
        mov     ax, 10
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [ballY]
        sar     ax, 1                       ; signed >>
        sar     ax, 1
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [subPxY], ax
; ---- subPxY2 = subPxY + ballH - 1
        mov     ax, [subPxY]
        add     ax, 3
        dec     ax
        mov     [subPxY2], ax
; ---- drawLineVertical( subPxX, subPxY, subPxY2, ballColor )
        mov     ax, [subPxX]
        mov     [drawLineVertical__x], al   ; narrowed to u8
        mov     ax, [subPxY]
        mov     [drawLineVertical__y1], al  ; narrowed to u8
        mov     ax, [subPxY2]
        mov     [drawLineVertical__y2], al  ; narrowed to u8
        mov     al, [ballColor]
        mov     [drawLineVertical__color], al; u8 -> u8, no widening
        call    drawLineVertical
; ---- drawLineVertical( subPxX + 1, subPxY, subPxY2, ballColor )
        mov     ax, [subPxX]
        inc     ax
        mov     [drawLineVertical__x], al   ; narrowed to u8
        mov     ax, [subPxY]
        mov     [drawLineVertical__y1], al  ; narrowed to u8
        mov     ax, [subPxY2]
        mov     [drawLineVertical__y2], al  ; narrowed to u8
        mov     al, [ballColor]
        mov     [drawLineVertical__color], al; u8 -> u8, no widening
        call    drawLineVertical
; ---- drawLineVertical( subPxX + 2, subPxY, subPxY2, ballColor )
        mov     ax, [subPxX]
        add     ax, 2
        mov     [drawLineVertical__x], al   ; narrowed to u8
        mov     ax, [subPxY]
        mov     [drawLineVertical__y1], al  ; narrowed to u8
        mov     ax, [subPxY2]
        mov     [drawLineVertical__y2], al  ; narrowed to u8
        mov     al, [ballColor]
        mov     [drawLineVertical__color], al; u8 -> u8, no widening
        call    drawLineVertical
        ret

; ============================================== sub clearBall ====

clearBall:
; ---- subPxX = subgridToPx( playLeft, oBallX )
        mov     ax, 41
