        mov     ax, [oBallX]
        sar     ax, 1                       ; signed >>
        sar     ax, 1
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [subPxX], ax
; ---- subPxY = subgridToPx( playTop, oBallY )
        mov     ax, 10
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [oBallY]
        sar     ax, 1                       ; signed >>
        sar     ax, 1
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [subPxY], ax
; ---- subPxY2 = subPxY + ballH - 1
        mov     ax, [subPxY]
        add     ax, 3
        dec     ax
        mov     [subPxY2], ax
; ---- drawLineVertical( subPxX, subPxY, subPxY2, lightGreen )
        mov     ax, [subPxX]
        mov     [drawLineVertical__x], al   ; narrowed to u8
        mov     ax, [subPxY]
        mov     [drawLineVertical__y1], al  ; narrowed to u8
        mov     ax, [subPxY2]
        mov     [drawLineVertical__y2], al  ; narrowed to u8
        mov     byte [drawLineVertical__color], 1
        call    drawLineVertical
; ---- drawLineVertical( subPxX + 1, subPxY, subPxY2, lightGreen )
        mov     ax, [subPxX]
        inc     ax
        mov     [drawLineVertical__x], al   ; narrowed to u8
        mov     ax, [subPxY]
        mov     [drawLineVertical__y1], al  ; narrowed to u8
        mov     ax, [subPxY2]
        mov     [drawLineVertical__y2], al  ; narrowed to u8
        mov     byte [drawLineVertical__color], 1
        call    drawLineVertical
; ---- drawLineVertical( subPxX + 2, subPxY, subPxY2, lightGreen )
        mov     ax, [subPxX]
        add     ax, 2
        mov     [drawLineVertical__x], al   ; narrowed to u8
        mov     ax, [subPxY]
        mov     [drawLineVertical__y1], al  ; narrowed to u8
        mov     ax, [subPxY2]
        mov     [drawLineVertical__y2], al  ; narrowed to u8
        mov     byte [drawLineVertical__color], 1
        call    drawLineVertical
        ret

; ============================================== sub drawSprite ====

drawSprite:
; ---- tile = index * 25
        mov     al, [drawSprite__index]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, 25
        mul     bx                          ; low 16 bits are sign-agnostic
        mov     [tile], ax
; ---- for( j = 0; j < 5; j++ ){
        mov     byte [j], 0
.L98:
        mov     al, [j]
        cmp     al, 5                       ; byte operands, no widening
        jb      .L101                       ; unsigned <
        jmp     .L100
.L101:
; ---- for( i = 0; i < 5; i++ ){
        mov     byte [i], 0
.L102:
        mov     al, [i]
        cmp     al, 5                       ; byte operands, no widening
        jb      .L105                       ; unsigned <
        jmp     .L104
.L105:
; ---- setPixel( i + dx, j + dy, textSprites[ tile ] )
        mov     al, [i]
        xor     ah, ah                      ; u8 -> u16
        mov     bl, [drawSprite__dx]
        xor     bh, bh                      ; u8 -> u16
        add     ax, bx
        mov     [setPixel__x], ax
        mov     al, [j]
        xor     ah, ah                      ; u8 -> u16
        mov     bl, [drawSprite__dy]
        xor     bh, bh                      ; u8 -> u16
        add     ax, bx
        mov     [setPixel__y], ax
        mov     ax, [tile]
        mov     bx, ax
        mov     al, [textSprites + bx]
        mov     [setPixel__color], al       ; u8 -> u8, no widening
        call    setPixel
; ---- tile++
        inc     word [tile]
.L103:
        inc     byte [i]
        jmp     .L102
.L104:
.L99:
        inc     byte [j]
        jmp     .L98
.L100:
        ret

; ============================================== sub drawScore ====

drawScore:
; ---- if( score1 < 10 ){
        mov     al, [score1]
        cmp     al, 10                      ; byte operands, no widening
        jb      .L108                       ; unsigned <
        jmp     .L106
.L108:
; ---- digit0 = 0
        mov     byte [digit0], 0
; ---- digit1 = score1
        mov     al, [score1]
        mov     [digit1], al                ; u8 -> u8, no widening
        jmp     .L107
.L106:
; ---- digit0 = 1
        mov     byte [digit0], 1
; ---- digit1 = score1 - 10
        mov     al, [score1]
        xor     ah, ah                      ; u8 -> u16
        sub     ax, 10
        mov     [digit1], al                ; narrowed to u8
.L107:
; ---- if( score2 < 10 ){
        mov     al, [score2]
        cmp     al, 10                      ; byte operands, no widening
        jb      .L111                       ; unsigned <
        jmp     .L109
.L111:
; ---- digit2 = 0
        mov     byte [digit2], 0
; ---- digit3 = score2
        mov     al, [score2]
        mov     [digit3], al                ; u8 -> u8, no widening
        jmp     .L110
.L109:
; ---- digit2 = 1
        mov     byte [digit2], 1
; ---- digit3 = score2 - 10
        mov     al, [score2]
        xor     ah, ah                      ; u8 -> u16
        sub     ax, 10
        mov     [digit3], al                ; narrowed to u8
.L110:
; ---- drawSprite( digit0, scoreX0, scoreY )
        mov     al, [digit0]
        mov     [drawSprite__index], al     ; u8 -> u8, no widening
        mov     byte [drawSprite__dx], 44
        mov     byte [drawSprite__dy], 85
        call    drawSprite
; ---- drawSprite( digit1, scoreX1, scoreY )
        mov     al, [digit1]
        mov     [drawSprite__index], al     ; u8 -> u8, no widening
        mov     byte [drawSprite__dx], 51
        mov     byte [drawSprite__dy], 85
        call    drawSprite
; ---- drawSprite( digit2, scoreX2, scoreY )
        mov     al, [digit2]
        mov     [drawSprite__index], al     ; u8 -> u8, no widening
        mov     byte [drawSprite__dx], 101
        mov     byte [drawSprite__dy], 85
        call    drawSprite
; ---- drawSprite( digit3, scoreX3, scoreY )
        mov     al, [digit3]
        mov     [drawSprite__index], al     ; u8 -> u8, no widening
        mov     byte [drawSprite__dx], 108
        mov     byte [drawSprite__dy], 85
        call    drawSprite
        ret

; ============================================== sub movePaddle ====

movePaddle:
; ---- if ( up || down ) {
        mov     al, [movePaddle__up]
        test    al, al
        jz      .L115
        jmp     .L114
.L115:
        mov     al, [movePaddle__down]
        test    al, al
        jnz     .L116
        jmp     .L112
.L116:
.L114:
; ---- if ( up ) player[ pi ].y -= player[ pi ].speed
        mov     al, [movePaddle__up]
        test    al, al
        jnz     .L119
        jmp     .L117
.L119:
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [player__y + bx]
        push    ax                          ; save lhs: rhs is not a leaf
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [player__speed + bx]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        pop     ax
        sub     ax, bx
        push    ax                          ; save value while computing the index
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        pop     ax
        mov     [player__y + bx], ax
.L117:
; ---- if ( down ) player[ pi ].y += player[ pi ].speed
        mov     al, [movePaddle__down]
        test    al, al
        jnz     .L122
        jmp     .L120
.L122:
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [player__y + bx]
        push    ax                          ; save lhs: rhs is not a leaf
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [player__speed + bx]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        pop     ax
        add     ax, bx
        push    ax                          ; save value while computing the index
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        pop     ax
        mov     [player__y + bx], ax
.L120:
; ---- if ( player[ pi ].y < 0 ) player[ pi ].y = 0
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [player__y + bx]
        test    ax, ax
        jl      .L125                       ; signed <
        jmp     .L123
.L125:
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     word [player__y + bx], 0
.L123:
; ---- if ( player[ pi ].y > paddleYMax ) player[ pi ].y = paddleYMax
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [player__y + bx]
        cmp     ax, 244
        jg      .L128                       ; signed >
        jmp     .L126
.L128:
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     word [player__y + bx], 244
.L126:
; ---- if ( player[ pi ].speed < paddleSpeedMax ) {
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [player__speed + bx]
        cmp     al, 16                      ; byte operands, no widening
        jb      .L131                       ; unsigned <
        jmp     .L129
.L131:
; ---- player[ pi ].speed += paddleSpeedStep
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [player__speed + bx]
        xor     ah, ah                      ; u8 -> u16
        add     ax, 2
        push    ax                          ; save value while computing the index
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        pop     ax
        mov     [player__speed + bx], al
.L129:
        jmp     .L113
.L112:
; ---- player[ pi ].speed = 0
        mov     al, [movePaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     byte [player__speed + bx], 0
.L113:
        ret

; ============================================== sub input ====

input:
; ---- pollKeyboard()
        call    pollKeyboard
; ---- if( wasEsc ){
        mov     al, [wasEsc]
        test    al, al
        jnz     .L134
        jmp     .L132
.L134:
; ---- isRunning = false
        mov     byte [isRunning], 0
; ---- return
        ret
.L132:
; ---- movePaddle( 0, isUp1, isDown1 )
        mov     byte [movePaddle__pi], 0
        mov     al, [isUp1]
        mov     [movePaddle__up], al        ; bool -> bool, no widening
        mov     al, [isDown1]
        mov     [movePaddle__down], al      ; bool -> bool, no widening
        call    movePaddle
; ---- movePaddle( 1, isUp2, isDown2 )
        mov     byte [movePaddle__pi], 1
        mov     al, [isUp2]
        mov     [movePaddle__up], al        ; bool -> bool, no widening
        mov     al, [isDown2]
        mov     [movePaddle__down], al      ; bool -> bool, no widening
        call    movePaddle
        ret

; ============================================== sub update ====

update:
; ---- ballX += ballSpeedX
        mov     ax, [ballX]
        mov     bx, [ballSpeedX]
        add     ax, bx
        mov     [ballX], ax
; ---- ballY += ballSpeedY
        mov     ax, [ballY]
        mov     bx, [ballSpeedY]
        add     ax, bx
        mov     [ballY], ax
; ---- drawScore()
        call    drawScore
        ret

; ============================================== sub waitMicros ====

waitMicros:
; ---- _ah = 0x86
        mov     byte [_ah], 134
; ---- _cx = high
        mov     ax, [waitMicros__high]
        mov     [_cx], ax
; ---- _dx = low
        mov     ax, [waitMicros__low]
        mov     [_dx], ax
; ---- int 0x15
        call    int15
        ret

; ============================================== sub doWait ====

doWait:
; ---- sub doWait => waitMicros( 0, frameMicros )
        mov     word [waitMicros__high], 0
        mov     word [waitMicros__low], 33333
        call    waitMicros
        ret

; ============================================== sub render ====

render:
; ---- clearBall()
        call    clearBall
; ---- clearPaddle( 0 )
        mov     byte [clearPaddle__pi], 0
        call    clearPaddle
; ---- clearPaddle( 1 )
        mov     byte [clearPaddle__pi], 1
        call    clearPaddle
; ---- drawNet()
        call    drawNet
; ---- drawBall()
        call    drawBall
; ---- drawPaddle( 0 )
        mov     byte [drawPaddle__pi], 0
        call    drawPaddle
; ---- drawPaddle( 1 )
        mov     byte [drawPaddle__pi], 1
        call    drawPaddle
; ---- player[ 0 ].oldY = player[ 0 ].y
        mov     ax, [player__y]
        mov     [player__oldY], ax
; ---- player[ 1 ].oldY = player[ 1 ].y
        mov     ax, [player__y + 2]
        mov     [player__oldY + 2], ax
; ---- oBallX = ballX
        mov     ax, [ballX]
        mov     [oBallX], ax
; ---- oBallY = ballY
        mov     ax, [ballY]
        mov     [oBallY], ax
        ret

; ============================================== sub tick ====

tick:
; ---- input()
        call    input
; ---- update()
        call    update
; ---- render()
        call    render
; ---- doWait()
        call    doWait
        ret

; ============================================== sub serve ====

serve:
; ---- ballSpeedY = 0
        mov     word [ballSpeedY], 0
; ---- volleyCount = 0
        mov     byte [volleyCount], 0
; ---- ballX = serveX[ ballPlayer ]
        mov     al, [ballPlayer]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [serveX + bx]
        mov     [ballX], ax
; ---- ballY = player[ ballPlayer ].y + ballServeOffset
        mov     al, [ballPlayer]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [player__y + bx]
        add     ax, 12
        mov     [ballY], ax
; ---- ballSpeedX = serveSpeedX[ ballPlayer ]
        mov     al, [ballPlayer]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [serveSpeedX + bx]
        mov     [ballSpeedX], ax
; ---- ballColor = paddleColor[ ballPlayer ]
        mov     al, [ballPlayer]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [paddleColor + bx]
        mov     [ballColor], al             ; u8 -> u8, no widening
        ret

; ============================================== sub start ====

start:
; ---- seedRandom( ticks() )
        call    ticks
        mov     ax, [ticks__ret]
        mov     [seedRandom__s], ax
        call    seedRandom
; ---- isWinScreen = false
        mov     byte [isWinScreen], 0
; ---- score1 = 0
        mov     byte [score1], 0
; ---- score2 = 0
        mov     byte [score2], 0
; ---- player[ 0 ].speed = 0
        mov     byte [player__speed], 0
; ---- player[ 0 ].y = paddleYHome
        mov     word [player__y], 122
; ---- player[ 0 ].oldY = paddleYHome
        mov     word [player__oldY], 122
; ---- player[ 1 ].speed = 0
        mov     byte [player__speed + 1], 0
; ---- player[ 1 ].y = paddleYHome
        mov     word [player__y + 2], 122
; ---- player[ 1 ].oldY = paddleYHome
        mov     word [player__oldY + 2], 122
; ---- ballPlayer = randomBelow( len( player ) )
        mov     word [randomBelow__n], 2
        call    randomBelow
        mov     ax, [randomBelow__ret]
        mov     [ballPlayer], al            ; narrowed to u8
; ---- drawBackground()
        call    drawBackground
; ---- drawPlayfield()
        call    drawPlayfield
; ---- serve()
        call    serve
; ---- oBallX = ballX
        mov     ax, [ballX]
        mov     [oBallX], ax
; ---- oBallY = ballY
        mov     ax, [ballY]
        mov     [oBallY], ax
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int15:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x15
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

; ============================================================ data ====

; ---- reserved globals: the machine registers ----
_ax             dw      0
_al             equ     _ax
_ah             equ     _ax + 1
_bx             dw      0
_bl             equ     _bx
_bh             equ     _bx + 1
_cx             dw      0
_cl             equ     _cx
_ch             equ     _cx + 1
_dx             dw      0
_dl             equ     _dx
_dh             equ     _dx + 1
_si             dw      0
_di             dw      0

; ---- variables ----
rand__randomSeed dw      42        ; u16 = 42
seedRandom__s   dw      0        ; u16
nextRandom__ret dw      0        ; u16
randomBelow__n  dw      0        ; u16
randomBelow__ret dw      0        ; u16
ticks__ret      dw      0        ; u16
isUp1           db      0        ; bool
